export function triples(n: number): number {
  let count = 0;
  for (let c = 1; c <= n; c++) {
    for (let b = 1; b < c; b++) {
      for (let a = 1; a < b; a++) {
        if (a * a + b * b === c * c) {
          count++;
        }
      }
    }
  }
  return count;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { triples } from "./triples.js";

test("triples", () => {
  assert.equal(triples(5), 1);
  assert.equal(triples(20), 6);
});
